from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

from itertools import product

# --- Helper functions ---
def hamming(a: List[int], b: List[int]) -> int:
    return sum(x != y for x, y in zip(a, b))

def all_binary_vectors(dim: int):
    return [list(vec) for vec in product([0, 1], repeat=dim)]

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # We store our own state in the model (persistent between calls)
        if not hasattr(self._model, 'custom_ep_state'):
            self._model.custom_ep_state = {
                'guesses': [],  # List of (guess, is_particle)
                'found_particles': []  # List of particle positions
            }

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        state = self._model.custom_ep_state

        # Update history based on the last probe
        if prev_guess is not None:
            state['guesses'].append((prev_guess, is_particle))
            if is_particle:
                # Save found particle
                already_found = any(g == prev_guess for g in state['found_particles'])
                if not already_found:
                    state['found_particles'].append(list(prev_guess))

        # If we've found all particles, just return the first available untried position
        if len(state['found_particles']) >= num_particles:
            # Purposefully pick a dummy (e.g. all zeros), but it's arbitrary
            next_guess = [0] * dimension
        else:
            # Set of all possible positions to probe (unprobed and not excluded by min distance)
            probed = set(tuple(g) for g, _ in state['guesses'])
            found_particles = state['found_particles']

            # For small dimension, enumerate all, else random sample
            max_enumerate = 14  # Up to 2^14 positions can be handled easily
            candidate = None

            if dimension <= max_enumerate:
                all_positions = all_binary_vectors(dimension)
                candidates = []
                for pos in all_positions:
                    tpos = tuple(pos)
                    if tpos in probed:
                        continue
                    too_close = False
                    for fp in found_particles:
                        if hamming(pos, fp) < distance:
                            too_close = True
                            break
                    if not too_close:
                        candidates.append(pos)
                # Simple heuristic: pick lex smallest
                if candidates:
                    candidate = candidates[0]
                else:
                    # Everything excluded, fallback to unprobed
                    for pos in all_positions:
                        if tuple(pos) not in probed:
                            candidate = pos
                            break
            else:
                # For large dim, randomly try lex order bits
                # Try all zeros first
                base = [0]*dimension
                def valid(pos):
                    tpos = tuple(pos)
                    if tpos in probed:
                        return False
                    for fp in found_particles:
                        if hamming(pos, fp) < distance:
                            return False
                    return True
                if valid(base):
                    candidate = base
                # Otherwise scan bit-by-bit (limited to, say, first 100 positions)
                if candidate is None:
                    for idx in range(min(512, 2**dimension)):
                        # Make a binary vector from idx
                        pos = [(idx >> i) & 1 for i in reversed(range(dimension))]
                        if valid(pos):
                            candidate = pos
                            break
                # Absolute fallback: find any unprobed position
                if candidate is None:
                    for idx in range(min(10000, 2**dimension)):
                        pos = [(idx >> i) & 1 for i in reversed(range(dimension))]
                        tpos = tuple(pos)
                        if tpos not in probed:
                            candidate = pos
                            break
                if candidate is None:
                    # This should not happen: fall back
                    candidate = [0]*dimension
            next_guess = candidate

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

