# Helper function for hamming distance
def hamming_distance(a: List[int], b: List[int]) -> int:
    return sum(x != y for x, y in zip(a, b))

def to_tuple(l):
    return tuple(l)

def from_tuple(t):
    return list(t)

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # State keeping for found particles and previous guesses
        self._initialized = False
        self.found_particles = []  # list of tuple
        self.probed_positions = set()  # set of tuple
        self.dimension = None
        self.num_particles = None
        self.distance = None

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def is_valid_probe(self, pos):
        # Not within distance-1 of any found particle
        for fp in self.found_particles:
            if hamming_distance(fp, pos) < self.distance:
                return False
        return True

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']
        next_guess = None

        # init state on first call or if dimension/parameters change
        if not self._initialized or (self.dimension != dimension or self.num_particles != num_particles or self.distance != distance):
            self.dimension = dimension
            self.num_particles = num_particles
            self.distance = distance
            self.found_particles = []
            self.probed_positions = set()
            self._initialized = True

        # Maintain history
        if prev_guess is not None:
            tu = to_tuple(prev_guess)
            self.probed_positions.add(tu)
            if is_particle and (tu not in self.found_particles):
                self.found_particles.append(tu)

        # If found all particles, we do not probe further (but per protocol, must give something)
        if len(self.found_particles) >= self.num_particles:
            # Defensive programming: just pick the first unprobed point respecting min dist
            for p in product([0,1], repeat=dimension):
                if p not in self.probed_positions and self.is_valid_probe(p):
                    next_guess = list(p)
                    break
            else:
                next_guess = [0]*dimension
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_guess, type='custom')]
            )

        # Greedy: Try all points lexicographically, probe one which is not within forbidden distance
        # (distance-1) away from any found particle and not already probed
        for p in product([0,1], repeat=dimension):
            ptu = p
            if ptu in self.probed_positions:
                continue
            if self.is_valid_probe(ptu):
                next_guess = list(ptu)
                break
        else:
            # If not found, just return first not-probed (should not happen normally)
            for p in product([0,1], repeat=dimension):
                if p not in self.probed_positions:
                    next_guess = list(p)
                    break
            else:
                next_guess = [0]*dimension

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

