from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Set, Tuple
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

import itertools

# --- Helper portion ---
def hamming_distance(a: List[int], b: List[int]) -> int:
    return sum(x != y for x, y in zip(a, b))

def all_binary_vectors(n: int):
    return (list(map(int, v)) for v in itertools.product((0,1), repeat=n))

def within_distance(vec: List[int], others: List[List[int]], min_hamming: int) -> bool:
    """Return True iff vec is within min_hamming of any in others."""
    for p in others:
        if hamming_distance(vec, p) < min_hamming:
            return True
    return False

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

        # State variables to track known particles and forbidden regions between turns
        # We use _model._extra_state as a dict to persist info across calls
        if not hasattr(self._model, '_extra_state'):
            self._model._extra_state = {}

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        # --- Persistent state management ---
        state = self._model._extra_state
        if 'found_particles' not in state:
            state['found_particles'] = []     # List[List[int]]
        if 'probed_set' not in state:
            state['probed_set'] = set()      # Set[tuple]

        found_particles: List[List[int]] = state['found_particles']
        probed_set: Set[Tuple[int,...]] = state['probed_set']

        # Bookkeeping of response (except for first turn)
        if prev_guess is not None:
            guess_tuple = tuple(prev_guess)
            probed_set.add(guess_tuple)
            if is_particle:
                if prev_guess not in found_particles:
                    found_particles.append(prev_guess)

        # Systematic candidate testing:
        next_guess = None
        # If enough found, skip probing (unlikely to be called in game, just for completeness)
        if len(found_particles) >= num_particles:
            # Make a dummy probe: just return any unprobed vector (shouldn't happen)
            for vec in all_binary_vectors(dimension):
                if tuple(vec) not in probed_set:
                    next_guess = vec
                    break
            if next_guess is None:
                next_guess = [0]*dimension
        else:
            # Enumerate the space (by default, lexicographical order)
            for vec in all_binary_vectors(dimension):
                tvec = tuple(vec)
                if tvec in probed_set:
                    continue # Already probed
                if within_distance(vec, found_particles, distance):
                    continue # Too close to already found particle
                # This is an admissible new probe
                next_guess = vec
                break
            # All excluded: fallback to anything
            if next_guess is None:
                # Shouldn't occur unless we've found all particles
                for vec in all_binary_vectors(dimension):
                    if tuple(vec) not in probed_set:
                        next_guess = vec
                        break
                if next_guess is None:
                    next_guess = [0]*dimension
        # Bookkeeping for next turn
        state['found_particles'] = found_particles
        state['probed_set'] = probed_set

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

