# Helper: Hamming distance
def hamming(a: Tuple[int, ...], b: Tuple[int, ...]) -> int:
    return sum((x != y) for x, y in zip(a, b))

def neighbors(center: Tuple[int, ...], max_dist: int) -> Set[Tuple[int, ...]]:
    # All binary vectors within max_dist from center (inclusive)
    # Exponential, but only generated for individual balls around found particles
    n = len(center)
    result = set()
    for mask in range(1 << n):
        flips = [ (mask>>j)&1 for j in range(n) ]
        idxs = [j for j, f in enumerate(flips) if f]
        if len(idxs) <= max_dist:
            neighbor = list(center)
            for j in idxs:
                neighbor[j] ^= 1
            result.add(tuple(neighbor))
    return result

# For iterating over all binary vectors lex order
class BinaryEnumerator:
    def __init__(self, d):
        self.d = d
        self.i = 0
        self.max = 1<<d
    def __iter__(self):
        return self
    def __next__(self):
        if self.i >= self.max:
            raise StopIteration
        res = [(self.i>>j)&1 for j in range(self.d-1,-1,-1)]
        self.i += 1
        return tuple(res)

