def hamming_distance(x: List[int], y: List[int]) -> int:
    return sum(a != b for a, b in zip(x, y))

def all_hypercube_points(dimension: int):
    # Generator for all 0/1 vectors of length dimension
    return (list(bits) for bits in itertools.product([0,1], repeat=dimension))

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # Custom fields for state tracking during the session
        if not hasattr(self._model, '_ep_possible_points'):
            self._model._ep_possible_points = None # all possible points (cache)
        if not hasattr(self._model, '_ep_probed_set'):
            self._model._ep_probed_set = set()
        if not hasattr(self._model, '_ep_particles_found'):
            self._model._ep_particles_found = []
        if not hasattr(self._model, '_ep_candidates'):
            self._model._ep_candidates = None

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']
        next_guess = None

        model = self._model
        # 1. If needed, initialize all hypercube points
        if getattr(model, '_ep_possible_points', None) is None or len(getattr(model, '_ep_possible_points')) != (1<<dimension):
            model._ep_possible_points = [p for p in all_hypercube_points(dimension)]
            # Because dimension may change between games
            model._ep_probed_set = set()
            model._ep_particles_found = []
            model._ep_candidates = None
        possible_points = model._ep_possible_points
        probed_set = model._ep_probed_set
        particles_found = model._ep_particles_found
        # 2. Update with feedback from last guess (if any)
        if prev_guess is not None:
            tup = tuple(prev_guess)
            probed_set.add(tup)
            # If we found a particle, track it
            if is_particle:
                if prev_guess not in particles_found:
                    particles_found.append(prev_guess[:])
        # 3. If we have already found all required particles, don't probe further
        if len(particles_found) >= num_particles:
            # As a protocol, just return dummy value
            next_guess = list(particles_found[0])
        else:
            # 4. Prune candidate list:  Only consider positions:
            # (a) Not yet probed
            # (b) Not within distance-1 of any found particle
            possible = []
            for pt in possible_points:
                tup = tuple(pt)
                if tup in probed_set:
                    continue
                exclude = False
                for pf in particles_found:
                    if hamming_distance(pt, pf) < distance:
                        exclude = True
                        break
                if not exclude:
                    possible.append(pt)
            # If first move (no probe yet), pick all-zeros
            if prev_guess is None:
                next_guess = [0]*dimension
            else:
                if possible:
                    # Option: Sort for deterministic probe order (lexicographical)
                    possible.sort()
                    next_guess = possible[0]
                else:
                    # Fallback: Pick the next not yet probed position (even if forbidden by exclusion, as there may be hidden error or corner case)
                    for pt in possible_points:
                        tup = tuple(pt)
                        if tup not in probed_set:
                            next_guess = list(pt)
                            break
                    if next_guess is None:
                        # Should not happen, but fallback to [1]*dimension
                        next_guess = [1]*dimension
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

